const getErrorMessage = (error: unknown): string => {
    if (error && typeof error === "object") {
        const typedError = error as { error?: string; errorMsg?: string; errors?: string[] };
        if (typedError.error) {
            return typedError.error;
        }
        if (typedError.errorMsg) {
            return typedError.errorMsg;
        }
        if (typedError.errors && typedError.errors.length > 0) {
            return typedError.errors.join("\n");
        }
    }

    if (error instanceof Error) {
        return error.message;
    }

    return "生成失败，请稍后重试";
};

async function fetchWorkflowApi(jsonPath: string): Promise<object> {
    const res = await fetch(jsonPath);
    if (!res.ok) {
        throw new Error(`Failed to load workflow: ${jsonPath}`);
    }
    const data = await res.json();
    const workflow = data.workflows?.[0];
    if (!workflow?.workflowApiJSON) {
        throw new Error(`workflowApiJSON not found in ${jsonPath}`);
    }
    return workflow.workflowApiJSON;
}

/**
 * Fetch complete workflow including viewComfyJSON and workflowApiJSON
 */
async function fetchCompleteWorkflow(jsonPath: string): Promise<{ viewComfyJSON: any; workflowApiJSON: any }> {
    const res = await fetch(jsonPath);
    if (!res.ok) {
        throw new Error(`Failed to load workflow: ${jsonPath}`);
    }
    const data = await res.json();
    const workflow = data.workflows?.[0];
    if (!workflow?.workflowApiJSON || !workflow?.viewComfyJSON) {
        throw new Error(`Missing workflow data in ${jsonPath}`);
    }
    return {
        viewComfyJSON: workflow.viewComfyJSON,
        workflowApiJSON: workflow.workflowApiJSON,
    };
}

/**
 * Deep clone an object to avoid mutations
 */
function deepClone(obj: any): any {
    if (obj === null || typeof obj !== "object") return obj;
    if (Array.isArray(obj)) return obj.map((item) => deepClone(item));
    const cloned: any = {};
    for (const key in obj) {
        if (obj.hasOwnProperty(key)) {
            cloned[key] = deepClone(obj[key]);
        }
    }
    return cloned;
}

/**
 * Update a nested object using a path array
 * Example: setValueByPath(obj, ["31", "inputs", "seed"], 123)
 */
function setValueByPath(obj: any, path: string[], value: unknown): void {
    if (path.length === 0) return;
    let current = obj;
    for (let i = 0; i < path.length - 1; i++) {
        const key = path[i];
        if (!(key in current)) {
            current[key] = {};
        }
        current = current[key];
    }
    current[path[path.length - 1]] = value;
}

/**
 * Check if a parameter/group should be visible in UI
 * Only 'active' or undefined visibility should be shown
 * Both 'deleted' and 'hidden' are hidden from UI
 */
function isVisibilityActive(visibility?: string): boolean {
    return visibility !== "deleted" && visibility !== "hidden";
}

/**
 * Check if a parameter/group should be submitted
 * Only 'deleted' is excluded from submission
 * 'hidden' parameters are submitted with original values
 */
function shouldSubmitParameter(visibility?: string): boolean {
    return visibility !== "deleted";
}

function isSeedInput(input: AdvancedInputItem): boolean {
    if (input.valueType === "seed") {
        return true;
    }
    const probe = `${input.key} ${input.title} ${input.placeholder ?? ""}`.toLowerCase();
    return probe.includes("seed") || probe.includes("noise_seed") || probe.includes("rand_seed");
}

async function fileToDataUrl(file: File): Promise<string> {
    return await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ""));
        reader.onerror = () => reject(new Error("读取文件失败"));
        reader.readAsDataURL(file);
    });
}

function dataUrlToFile(dataUrl: string, fileName: string, fileType: string): File {
    const [meta, base64Data] = dataUrl.split(",");
    if (!meta || !base64Data) {
        throw new Error("无效的媒体数据");
    }

    const binary = atob(base64Data);
    const len = binary.length;
    const bytes = new Uint8Array(len);

    for (let i = 0; i < len; i += 1) {
        bytes[i] = binary.charCodeAt(i);
    }

    return new File([bytes], fileName, { type: fileType || "application/octet-stream" });
}

async function serializeFileSnapshot(file: File | null): Promise<PersistedFileSnapshot | null> {
    if (!file) {
        return null;
    }

    return {
        fileName: file.name,
        fileType: file.type,
        dataUrl: await fileToDataUrl(file),
    };
}

function deserializeFileSnapshot(snapshot: PersistedFileSnapshot | null): File | null {
    if (!snapshot) {
        return null;
    }

    return dataUrlToFile(snapshot.dataUrl, snapshot.fileName, snapshot.fileType);
}

function createPreviewUrlOutputs(outputs: RuntimeCachedStudioOutput[]): StudioOutput[] {
    return outputs.map((output) => ({
        ...output,
        url: URL.createObjectURL(output.file),
    }));
}

function getVisibleImageStyleOptions(selectedStyle: string): typeof STYLE_OPTIONS {
    const pageSize = 4;

    if (STYLE_OPTIONS.length <= pageSize) {
        return STYLE_OPTIONS;
    }

    const selectedIndex = STYLE_OPTIONS.findIndex((item) => item.id === selectedStyle);
    if (selectedIndex < 0) {
        return STYLE_OPTIONS.slice(0, pageSize);
    }

    const start = Math.floor(selectedIndex / pageSize) * pageSize;
    const pageItems = STYLE_OPTIONS.slice(start, start + pageSize);

    if (pageItems.length === pageSize) {
        return pageItems;
    }

    return [...pageItems, ...STYLE_OPTIONS.slice(0, pageSize - pageItems.length)];
}

export default function StudioPage({ mode, background }: StudioPageProps) {
    const router = useRouter();
    const searchParams = useSearchParams();
    const { doPost } = usePostPlayground();
    const [imageWorkflow, setImageWorkflow] = React.useState<ImageWorkflow>("text");
    const [workName, setWorkName] = React.useState(DEFAULT_WORK_NAME);
    const [editingName, setEditingName] = React.useState(false);
    const [promptText, setPromptText] = React.useState("");
    const [selectedStyle, setSelectedStyle] = React.useState("");
    const [selectedMotion, setSelectedMotion] = React.useState(MOTION_OPTIONS[0]?.id ?? "");
    const [showStyleDialog, setShowStyleDialog] = React.useState(false);
    const [showAdvancedDialog, setShowAdvancedDialog] = React.useState(false);
    const [previewModal, setPreviewModal] = React.useState<PreviewModalState>({
        open: false,
        kind: "image",
    });
    const [generationState, setGenerationState] = React.useState<"idle" | "generating" | "ready">("idle");
    const [uploadedPreview, setUploadedPreview] = React.useState<string | null>(null);
    const [selectedThumb, setSelectedThumb] = React.useState(0);
    const [advancedSeed, setAdvancedSeed] = React.useState("11111");
    const [widthValue, setWidthValue] = React.useState("1328");
    const [heightValue, setHeightValue] = React.useState("1328");
    const [filePrefix, setFilePrefix] = React.useState("ComfyUI");
    const [isRandomized, setIsRandomized] = React.useState(true);
    const [modelControlStrength, setModelControlStrength] = React.useState(70);
    const [modelSurfaceStrength, setModelSurfaceStrength] = React.useState(50);
    const [modelStepCount, setModelStepCount] = React.useState(16);
    const [uploadedFile, setUploadedFile] = React.useState<File | null>(null);
    const [generatedOutputs, setGeneratedOutputs] = React.useState<StudioOutput[]>([]);
    const [generationError, setGenerationError] = React.useState<string | null>(null);
    const [copySuccessMessage, setCopySuccessMessage] = React.useState<string | null>(null);
    const [storageHintMessage, setStorageHintMessage] = React.useState<string | null>(null);
    const [actionHint, setActionHint] = React.useState<string | null>(null);
    const [isPromptEditing, setIsPromptEditing] = React.useState(false);
    const [isSoftKeyboardOpen, setIsSoftKeyboardOpen] = React.useState(false);
    const [isTouchDevice, setIsTouchDevice] = React.useState(false);
    const [advancedInputsConfig, setAdvancedInputsConfig] = React.useState<AdvancedInputGroup[]>([]);
    const [advancedInputValues, setAdvancedInputValues] = React.useState<Record<string, unknown>>({});
    const [advancedDraftValues, setAdvancedDraftValues] = React.useState<Record<string, unknown>>({});
    const fileInputRef = React.useRef<HTMLInputElement>(null);
    const workNameInputRef = React.useRef<HTMLInputElement>(null);
    const creativeInputRef = React.useRef<HTMLTextAreaElement>(null);
    const resultAreaRef = React.useRef<HTMLDivElement>(null);
    const hintTimerRef = React.useRef<number | null>(null);
    const imageWorkflowPanelStateRef = React.useRef<Partial<Record<ImageWorkflow, ImageWorkflowPanelState>>>({});
    const hasHydratedPersistedStateRef = React.useRef(false);
    const hasShownStorageHintRef = React.useRef(false);
    const resultAreaRectRef = React.useRef<{ top: number; left: number; width: number; height: number } | null>(null);
    const [frozenResultAreaStyle, setFrozenResultAreaStyle] = React.useState<React.CSSProperties | undefined>(undefined);

    const finishPromptEditing = React.useCallback(() => {
        creativeInputRef.current?.blur();
        setIsPromptEditing(false);
    }, []);

    const showActionHint = React.useCallback((message: string) => {
        setActionHint(message);
        if (hintTimerRef.current) {
            window.clearTimeout(hintTimerRef.current);
        }
        hintTimerRef.current = window.setTimeout(() => {
            setActionHint(null);
            hintTimerRef.current = null;
        }, 2000);
    }, []);

    const showStorageHint = React.useCallback(() => {
        if (hasShownStorageHintRef.current) {
            return;
        }
        hasShownStorageHintRef.current = true;
        setStorageHintMessage("历史较多，已切换为会话内暂存");
    }, []);

    const openAdvancedDialog = React.useCallback(() => {
        const nextDraft = { ...advancedInputValues };
        setAdvancedDraftValues(nextDraft);
        console.log("[Advanced Dialog] open", {
            mode,
            workflowType: mode === "image" ? imageWorkflow : mode,
            values: nextDraft,
        });
        setShowAdvancedDialog(true);
    }, [advancedInputValues, imageWorkflow, mode]);

    const cancelAdvancedDialog = React.useCallback((source: "backdrop" | "cancel") => {
        console.log("[Advanced Dialog] cancel", {
            source,
            draftValues: advancedDraftValues,
            committedValues: advancedInputValues,
        });
        setAdvancedDraftValues({ ...advancedInputValues });
        setShowAdvancedDialog(false);
    }, [advancedDraftValues, advancedInputValues]);

    const saveAdvancedDialog = React.useCallback(() => {
        console.log("[Advanced Dialog] confirm", {
            draftValues: advancedDraftValues,
            previousCommittedValues: advancedInputValues,
        });
        setAdvancedInputValues({ ...advancedDraftValues });
        setShowAdvancedDialog(false);
    }, [advancedDraftValues, advancedInputValues]);

    const isImageMode = mode === "image";
    const isVideoMode = mode === "video";
    const isModelMode = mode === "model";

    const visibleOutputs = React.useMemo(() => {
        if (!isImageMode) {
            return generatedOutputs;
        }
        return generatedOutputs.filter((output) => output.workflowSnapshot === imageWorkflow);
    }, [generatedOutputs, imageWorkflow, isImageMode]);

    React.useEffect(() => {
        setSelectedThumb((prev) => {
            if (visibleOutputs.length === 0) {
                return 0;
            }
            return Math.min(prev, visibleOutputs.length - 1);
        });
    }, [visibleOutputs.length]);

    const selectedOutput = visibleOutputs[selectedThumb] ?? visibleOutputs[0];
    const isPortraitMobile = useMediaQuery("(max-aspect-ratio: 999/1000)");
    const shouldCollapseResultPanel = (isTouchDevice && isPortraitMobile && isPromptEditing) || isSoftKeyboardOpen;

    React.useEffect(() => {
        if (shouldCollapseResultPanel) {
            return;
        }

        const node = resultAreaRef.current;
        if (!node || typeof ResizeObserver === "undefined") {
            return;
        }

        const updateRect = () => {
            const rect = node.getBoundingClientRect();
            resultAreaRectRef.current = {
                top: rect.top,
                left: rect.left,
                width: rect.width,
                height: rect.height,
            };
        };

        updateRect();
        const observer = new ResizeObserver(() => updateRect());
        observer.observe(node);
        window.addEventListener("resize", updateRect);

        return () => {
            observer.disconnect();
            window.removeEventListener("resize", updateRect);
        };
    }, [shouldCollapseResultPanel, mode, visibleOutputs.length, generationState]);

    React.useEffect(() => {
        if (!shouldCollapseResultPanel) {
            setFrozenResultAreaStyle(undefined);
            return;
        }

        const rect = resultAreaRectRef.current;
        if (!rect) {
            return;
        }

        setFrozenResultAreaStyle({
            position: "fixed",
            top: `${rect.top}px`,
            left: `${rect.left}px`,
            width: `${rect.width}px`,
            height: `${rect.height}px`,
            zIndex: 4,
            pointerEvents: "none",
        });
    }, [shouldCollapseResultPanel]);

    React.useEffect(() => {
        if (typeof window === "undefined") {
            return;
        }

        const viewport = window.visualViewport;
        if (!viewport) {
            return;
        }

        const touchCapable = navigator.maxTouchPoints > 0;
        setIsTouchDevice(touchCapable);
        if (!touchCapable) {
            return;
        }

        const updateKeyboardState = () => {
            const activeElement = document.activeElement as HTMLElement | null;
            const isTextEntry = Boolean(
                activeElement && (
                    activeElement.tagName === "TEXTAREA" ||
                    activeElement.tagName === "INPUT" ||
                    activeElement.isContentEditable
                )
            );
            const keyboardInset = Math.max(0, window.innerHeight - viewport.height - viewport.offsetTop);
            setIsSoftKeyboardOpen(isTextEntry && keyboardInset > 120);
        };

        const handleFocusOut = () => {
            window.setTimeout(updateKeyboardState, 60);
        };

        updateKeyboardState();
        viewport.addEventListener("resize", updateKeyboardState);
        viewport.addEventListener("scroll", updateKeyboardState);
        window.addEventListener("focusin", updateKeyboardState);
        window.addEventListener("focusout", handleFocusOut);

        return () => {
            viewport.removeEventListener("resize", updateKeyboardState);
            viewport.removeEventListener("scroll", updateKeyboardState);
            window.removeEventListener("focusin", updateKeyboardState);
            window.removeEventListener("focusout", handleFocusOut);
        };
    }, []);

    React.useEffect(() => {
        if (!isModelMode) {
            return;
        }

        void import("@google/model-viewer");
    }, [isModelMode]);

    const randomizeActiveSeedInputs = React.useCallback((groups: AdvancedInputGroup[]) => {
        setAdvancedInputValues((prev) => {
            const next = { ...prev };
            let changed = false;

            groups.forEach((group) => {
                if (!isVisibilityActive(group.visibility)) {
                    return;
                }
                group.inputs?.forEach((input) => {
                    if (!isVisibilityActive(input.visibility)) {
                        return;
                    }
                    if (!isSeedInput(input)) {
                        return;
                    }
                    next[input.key] = getComfyUIRandomSeed();
                    changed = true;
                });
            });

            return changed ? next : prev;
        });

        setAdvancedSeed(String(getComfyUIRandomSeed()));
    }, []);

    React.useEffect(() => {
        if (!editingName) {
            return;
        }

        const timer = window.setTimeout(() => {
            workNameInputRef.current?.focus();
        }, 0);

        return () => {
            window.clearTimeout(timer);
        };
    }, [editingName]);

    // Load advanced inputs config when workflow changes
    React.useEffect(() => {
        const loadAdvancedInputsConfig = async () => {
            try {
                const config = getWorkflowConfig(mode, imageWorkflow);
                const { viewComfyJSON } = await fetchCompleteWorkflow(config.jsonPath);

                if (viewComfyJSON?.advancedInputs && Array.isArray(viewComfyJSON.advancedInputs)) {
                    const advancedGroups: AdvancedInputGroup[] = (viewComfyJSON.advancedInputs as unknown[]).filter((group: any) => isVisibilityActive((group as AdvancedInputGroup).visibility)) as AdvancedInputGroup[];
                    setAdvancedInputsConfig(advancedGroups);

                    // Initialize advancedInputValues with default values (excluding non-active items)
                    const defaultValues: Record<string, unknown> = {};
                    advancedGroups.forEach((group) => {
                        group.inputs?.forEach((input) => {
                            if (isVisibilityActive(input.visibility)) {
                                defaultValues[input.key] = isSeedInput(input) ? getComfyUIRandomSeed() : input.value;
                            }
                        });
                    });
                    setAdvancedInputValues(defaultValues);
                    setAdvancedDraftValues(defaultValues);
                    setAdvancedSeed(String(getComfyUIRandomSeed()));
                } else {
                    setAdvancedInputsConfig([]);
                    setAdvancedInputValues({});
                    setAdvancedDraftValues({});
                }
            } catch (error) {
                // Silently fail if unable to load
                console.error("Error loading advanced inputs config:", error);
                setAdvancedInputsConfig([]);
                setAdvancedInputValues({});
                setAdvancedDraftValues({});
            }
        };

        void loadAdvancedInputsConfig();
    }, [mode, imageWorkflow]);

    const generatedOutputsRef = React.useRef(generatedOutputs);
    generatedOutputsRef.current = generatedOutputs;

    React.useEffect(() => {
        return () => {
            runtimeStudioOutputsCache[mode] = generatedOutputsRef.current.map((output) => ({
                file: output.file,
                promptTextSnapshot: output.promptTextSnapshot,
                uploadedFileSnapshot: output.uploadedFileSnapshot,
                workflowSnapshot: output.workflowSnapshot,
            }));
            for (const output of generatedOutputsRef.current) {
                URL.revokeObjectURL(output.url);
            }
        };
    }, [mode]);

    React.useEffect(() => {
        return () => {
            if (hintTimerRef.current) {
                window.clearTimeout(hintTimerRef.current);
            }
        };
    }, []);

    React.useEffect(() => {
        const clearSignal = window.sessionStorage.getItem(STUDIO_CLEAR_SIGNAL_KEY);
        if (clearSignal) {
            runtimeStudioOutputsCache.image = [];
            runtimeStudioOutputsCache.video = [];
            runtimeStudioOutputsCache.model = [];
            window.sessionStorage.removeItem(STUDIO_CLEAR_SIGNAL_KEY);
        }

        const requestedTab = mode === "image" ? searchParams.get("tab") : null;
        let activeWorkflow: ImageWorkflow | null = null;

        if (requestedTab === "text" || requestedTab === "line" || requestedTab === "magic") {
            activeWorkflow = requestedTab;
        }

        const restoreUploadFile = (file: File | null) => {
            setUploadedFile(file);
            setUploadedPreview(file ? URL.createObjectURL(file) : null);
            if (!fileInputRef.current || file) {
                return;
            }
            fileInputRef.current.value = "";
        };

        try {
            const panelsRaw = window.sessionStorage.getItem(STUDIO_PANELS_STORAGE_KEY);
            const outputsRaw = window.sessionStorage.getItem(STUDIO_OUTPUTS_STORAGE_KEY);

            if (panelsRaw) {
                const allPanels = JSON.parse(panelsRaw) as Partial<Record<StudioMode, PersistedStudioModeState>>;
                const persistedPanel = allPanels[mode];

                if (persistedPanel) {
                    if (mode === "image") {
                        activeWorkflow = activeWorkflow ?? persistedPanel.currentImageWorkflow ?? "text";
                        setImageWorkflow(activeWorkflow);
                    }

                    setWorkName(persistedPanel.workName || DEFAULT_WORK_NAME);
                    setSelectedMotion(persistedPanel.selectedMotion || (MOTION_OPTIONS[0]?.id ?? ""));

                    if (mode === "image" && persistedPanel.imageWorkflowPanelStates) {
                        const restoredPanelStates: Partial<Record<ImageWorkflow, ImageWorkflowPanelState>> = {};
                        for (const tab of IMAGE_TABS) {
                            const savedState = persistedPanel.imageWorkflowPanelStates[tab.id];
                            if (!savedState) {
                                continue;
                            }
                            restoredPanelStates[tab.id] = {
                                promptText: savedState.promptText,
                                uploadedFile: deserializeFileSnapshot(savedState.uploadedFileSnapshot),
                                selectedStyle: savedState.selectedStyle,
                                selectedThumb: savedState.selectedThumb,
                                generationState: savedState.generationState,
                            };
                        }
                        imageWorkflowPanelStateRef.current = restoredPanelStates;

                        const activePanelState = activeWorkflow ? restoredPanelStates[activeWorkflow] : null;
                        if (activePanelState) {
                            setPromptText(activePanelState.promptText);
                            setSelectedStyle(activePanelState.selectedStyle);
                            setSelectedThumb(activePanelState.selectedThumb);
                            setGenerationState(activePanelState.generationState);
                            restoreUploadFile(activePanelState.uploadedFile);
                        } else {
                            setPromptText(persistedPanel.promptText);
                            setSelectedStyle(persistedPanel.selectedStyle);
                            setSelectedThumb(persistedPanel.selectedThumb);
                            setGenerationState(persistedPanel.generationState);
                            restoreUploadFile(deserializeFileSnapshot(persistedPanel.uploadedFileSnapshot));
                        }
                    } else {
                        setPromptText(persistedPanel.promptText);
                        setSelectedStyle(persistedPanel.selectedStyle);
                        setSelectedThumb(persistedPanel.selectedThumb);
                        setGenerationState(persistedPanel.generationState);
                        restoreUploadFile(deserializeFileSnapshot(persistedPanel.uploadedFileSnapshot));
                    }
                } else if (activeWorkflow) {
                    setImageWorkflow(activeWorkflow);
                }
            } else if (activeWorkflow) {
                setImageWorkflow(activeWorkflow);
            }

            const runtimeCachedOutputs = runtimeStudioOutputsCache[mode];
            if (runtimeCachedOutputs && runtimeCachedOutputs.length > 0) {
                const restoredOutputs = createPreviewUrlOutputs(runtimeCachedOutputs);
                setGeneratedOutputs(restoredOutputs);
                generatedOutputsRef.current = restoredOutputs;
            } else if (outputsRaw && mode === "image") {
                const allOutputs = JSON.parse(outputsRaw) as Partial<Record<StudioMode, PersistedStudioOutput[]>>;
                const persistedOutputs = allOutputs[mode] ?? [];
                const restoredOutputs = persistedOutputs.map((output) => {
                    const restoredFile = deserializeFileSnapshot(output.fileSnapshot)!;
                    return {
                        file: restoredFile,
                        url: URL.createObjectURL(restoredFile),
                        promptTextSnapshot: output.promptTextSnapshot,
                        uploadedFileSnapshot: deserializeFileSnapshot(output.uploadedFileSnapshot),
                        workflowSnapshot: output.workflowSnapshot,
                    };
                });
                runtimeStudioOutputsCache[mode] = restoredOutputs.map((output) => ({
                    file: output.file,
                    promptTextSnapshot: output.promptTextSnapshot,
                    uploadedFileSnapshot: output.uploadedFileSnapshot,
                    workflowSnapshot: output.workflowSnapshot,
                }));
                setGeneratedOutputs(restoredOutputs);
                generatedOutputsRef.current = restoredOutputs;
            }
        } catch (error) {
            console.error("Failed to restore studio state:", error);
            window.sessionStorage.removeItem(STUDIO_PANELS_STORAGE_KEY);
            window.sessionStorage.removeItem(STUDIO_OUTPUTS_STORAGE_KEY);
        }

        const raw = window.sessionStorage.getItem(HANDOFF_STORAGE_KEY);
        if (raw) {
            try {
                const handoff = JSON.parse(raw) as StudioMediaHandoff;
                if (handoff.targetMode === mode) {
                    window.sessionStorage.removeItem(HANDOFF_STORAGE_KEY);

                    if (handoff.promptText) {
                        setPromptText(handoff.promptText);
                    }

                    if (mode === "image" && handoff.imageWorkflow) {
                        setImageWorkflow(handoff.imageWorkflow);
                    }

                    restoreUploadFile(dataUrlToFile(handoff.dataUrl, handoff.fileName, handoff.fileType));
                }
            } catch {
                window.sessionStorage.removeItem(HANDOFF_STORAGE_KEY);
            }
        }

        hasHydratedPersistedStateRef.current = true;
    }, [mode, searchParams]);

    React.useEffect(() => {
        if (!hasHydratedPersistedStateRef.current) {
            return;
        }

        let cancelled = false;
        const timer = window.setTimeout(() => {
            void (async () => {
                try {
                    const panelsRaw = window.sessionStorage.getItem(STUDIO_PANELS_STORAGE_KEY);
                    const allPanels = panelsRaw ? JSON.parse(panelsRaw) as Partial<Record<StudioMode, PersistedStudioModeState>> : {};

                    let imageWorkflowPanelStates: Partial<Record<ImageWorkflow, PersistedImageWorkflowPanelState>> | undefined;
                    if (isImageMode) {
                        const mergedPanelStates: Partial<Record<ImageWorkflow, ImageWorkflowPanelState>> = {
                            ...imageWorkflowPanelStateRef.current,
                            [imageWorkflow]: {
                                promptText,
                                uploadedFile,
                                selectedStyle,
                                selectedThumb,
                                generationState,
                            },
                        };
                        const serializedStates: Partial<Record<ImageWorkflow, PersistedImageWorkflowPanelState>> = {};
                        for (const tab of IMAGE_TABS) {
                            const panelState = mergedPanelStates[tab.id];
                            if (!panelState) {
                                continue;
                            }
                            serializedStates[tab.id] = {
                                promptText: panelState.promptText,
                                uploadedFileSnapshot: await serializeFileSnapshot(panelState.uploadedFile),
                                selectedStyle: panelState.selectedStyle,
                                selectedThumb: panelState.selectedThumb,
                                generationState: panelState.generationState,
                            };
                        }
                        imageWorkflowPanelStates = serializedStates;
                    }

                    allPanels[mode] = {
                        workName,
                        promptText,
                        selectedStyle,
                        selectedMotion,
                        selectedThumb,
                        generationState,
                        uploadedFileSnapshot: await serializeFileSnapshot(uploadedFile),
                        currentImageWorkflow: isImageMode ? imageWorkflow : undefined,
                        imageWorkflowPanelStates,
                    };

                    if (!cancelled) {
                        window.sessionStorage.setItem(STUDIO_PANELS_STORAGE_KEY, JSON.stringify(allPanels));
                    }
                } catch (error) {
                    console.error("Failed to persist studio panels:", error);
                    showStorageHint();
                }
            })();
        }, 120);

        return () => {
            cancelled = true;
            window.clearTimeout(timer);
        };
    }, [generationState, imageWorkflow, isImageMode, mode, promptText, selectedMotion, selectedStyle, selectedThumb, showStorageHint, uploadedFile, workName]);

    React.useEffect(() => {
        runtimeStudioOutputsCache[mode] = generatedOutputs.map((output) => ({
            file: output.file,
            promptTextSnapshot: output.promptTextSnapshot,
            uploadedFileSnapshot: output.uploadedFileSnapshot,
            workflowSnapshot: output.workflowSnapshot,
        }));
    }, [generatedOutputs, mode]);

    React.useEffect(() => {
        if (!hasHydratedPersistedStateRef.current) {
            return;
        }

        if (mode !== "image") {
            return;
        }

        let cancelled = false;
        const timer = window.setTimeout(() => {
            void (async () => {
                try {
                    const outputsRaw = window.sessionStorage.getItem(STUDIO_OUTPUTS_STORAGE_KEY);
                    const allOutputs = outputsRaw ? JSON.parse(outputsRaw) as Partial<Record<StudioMode, PersistedStudioOutput[]>> : {};

                    allOutputs[mode] = await Promise.all(generatedOutputs.map(async (output) => ({
                        fileSnapshot: await serializeFileSnapshot(output.file) as PersistedFileSnapshot,
                        promptTextSnapshot: output.promptTextSnapshot,
                        uploadedFileSnapshot: await serializeFileSnapshot(output.uploadedFileSnapshot),
                        workflowSnapshot: output.workflowSnapshot,
                    })));

                    if (!cancelled) {
                        window.sessionStorage.setItem(STUDIO_OUTPUTS_STORAGE_KEY, JSON.stringify(allOutputs));
                    }
                } catch (error) {
                    console.error("Failed to persist studio outputs:", error);
                    showStorageHint();
                }
            })();
        }, 120);

        return () => {
            cancelled = true;
            window.clearTimeout(timer);
        };
    }, [generatedOutputs, mode, showStorageHint]);

    const isUploadMode =
        isVideoMode || isModelMode || imageWorkflow === "line" || imageWorkflow === "magic";

    const sectionTitle = isVideoMode
        ? "运镜效果"
        : isModelMode
            ? ""
            : "推荐风格";

    const emptyText = isModelMode
        ? "在左侧上传图片..."
        : isVideoMode
            ? "在左侧输入灵感创意..."
            : imageWorkflow === "text"
                ? "在左侧输入灵感创意..."
                : "在左侧上传图片和描述...";

    const activeGalleryOptions = isVideoMode ? MOTION_OPTIONS : STYLE_OPTIONS;
    const activeGalleryLabel = isVideoMode ? "运镜效果" : "推荐风格";
    const motionLayout = isVideoMode
        ? isPortraitMobile
            ? "motion-portrait"
            : "motion-desktop"
        : "style";
    const isGenerateBlocked =
        generationState === "generating" ||
        (isImageMode && !promptText.trim() && !selectedStyle);

    const handleGenerate = async () => {
        setGenerationError(null);
        setGenerationState("generating");

        try {
            const config = getWorkflowConfig(mode, imageWorkflow);
            const workflowApi = await fetchWorkflowApi(config.jsonPath);
            const { keys } = config;

            const selectedStyleContent = isImageMode
                ? (STYLE_OPTIONS.find((item) => item.id === selectedStyle)?.content?.trim() ?? "")
                : "";
            const selectedMotionContent = isVideoMode
                ? (MOTION_OPTIONS.find((item) => item.id === selectedMotion)?.content?.trim() ?? "")
                : "";
            const promptForApi = [promptText.trim(), selectedStyleContent, selectedMotionContent]
                .filter((value) => value.length > 0)
                .join("，");

            const normalizeAdvancedValue = (valueType: string, rawValue: unknown): unknown => {
                if (valueType === "number" || valueType === "seed") {
                    const numVal = Number(rawValue);
                    return isNaN(numVal) ? rawValue : numVal;
                }
                if (valueType === "float") {
                    const floatVal = parseFloat(String(rawValue));
                    return isNaN(floatVal) ? rawValue : floatVal;
                }
                return rawValue;
            };

            const getAdvancedFinalValueByKey = (targetKey?: string): unknown | undefined => {
                if (!targetKey) return undefined;
                for (const group of advancedInputsConfig) {
                    if (!shouldSubmitParameter(group.visibility)) continue;
                    for (const input of group.inputs ?? []) {
                        if (!shouldSubmitParameter(input.visibility)) continue;
                        if (input.key !== targetKey) continue;
                        const rawValue = advancedInputValues[input.key] ?? input.value;
                        return normalizeAdvancedValue(input.valueType, rawValue);
                    }
                }
                return undefined;
            };

            const inputs: Array<{ key: string; value: unknown }> = [];

            if (keys.promptKey && promptForApi) {
                inputs.push({ key: keys.promptKey, value: promptForApi });
            }
            if (keys.imageKey && uploadedFile) {
                inputs.push({ key: keys.imageKey, value: uploadedFile });
            }
            if (keys.seedKey) {
                const effectiveSeed = getAdvancedFinalValueByKey(keys.seedKey);
                inputs.push({ key: keys.seedKey, value: effectiveSeed ?? Number(advancedSeed) });
            }
            if (keys.widthKey) {
                const effectiveWidth = getAdvancedFinalValueByKey(keys.widthKey);
                inputs.push({ key: keys.widthKey, value: effectiveWidth ?? Number(widthValue) });
            }
            if (keys.heightKey) {
                const effectiveHeight = getAdvancedFinalValueByKey(keys.heightKey);
                inputs.push({ key: keys.heightKey, value: effectiveHeight ?? Number(heightValue) });
            }
            inputs.push({ key: keys.prefixKey, value: filePrefix });

            // Deep clone workflowApi to avoid mutations
            const modifiedWorkflow = deepClone(workflowApi);
            const advancedUpdatesDebug: Array<{
                key: string;
                title: string;
                workflowPath: string[];
                originalValue: unknown;
                userValue: unknown;
                finalValue: unknown;
            }> = [];

            // Update workflowApiJSON with advanced input values based on workflowPath
            if (advancedInputsConfig.length > 0) {
                advancedInputsConfig.forEach((group) => {
                    if (!shouldSubmitParameter(group.visibility)) return;
                    group.inputs?.forEach((input) => {
                        if (!shouldSubmitParameter(input.visibility)) return;
                        const userValue = advancedInputValues[input.key];
                        if (userValue !== undefined && userValue !== null) {
                            // Skip if value hasn't changed from default
                            if (userValue === input.value) return;

                            // Convert string values to proper types
                            const finalValue = normalizeAdvancedValue(input.valueType, userValue);

                            // Update the workflow using workflowPath
                            setValueByPath(modifiedWorkflow, input.workflowPath, finalValue);
                            advancedUpdatesDebug.push({
                                key: input.key,
                                title: input.title,
                                workflowPath: input.workflowPath,
                                originalValue: input.value,
                                userValue,
                                finalValue,
                            });
                        }
                    });
                });
            }

            console.log("[Studio Submit] payload before doPost", {
                mode,
                workflowType: isImageMode ? imageWorkflow : mode,
                viewComfyInputs: inputs,
                advancedUpdates: advancedUpdatesDebug,
            });

            await doPost({
                viewComfy: {
                    inputs,
                    textOutputEnabled: false,
                    assetMetadata: {
                        title: workName,
                        promptText: promptText,
                        mediaType: mode,
                        workflowType: isImageMode ? imageWorkflow : null,
                    },
                },
                workflow: modifiedWorkflow,
                viewcomfyEndpoint: "",
                onSuccess: ({ outputs }) => {
                    const previousLength = isImageMode
                        ? generatedOutputsRef.current.filter((output) => output.workflowSnapshot === imageWorkflow).length
                        : generatedOutputsRef.current.length;
                    const newItems = outputs.map((file) => ({
                        file,
                        url: URL.createObjectURL(file),
                        promptTextSnapshot: promptText,
                        uploadedFileSnapshot: uploadedFile,
                        workflowSnapshot: isImageMode ? imageWorkflow : mode,
                    }));
                    setGeneratedOutputs((prev) => {
                        const combined = [...prev, ...newItems];
                        generatedOutputsRef.current = combined;
                        return combined;
                    });
                    // Always focus the latest newly generated output
                    setSelectedThumb(Math.max(0, previousLength + newItems.length - 1));
                    setGenerationState("ready");

                    // Prepare a fresh random seed for next generation
                    randomizeActiveSeedInputs(advancedInputsConfig);
                },
                onError: (error) => {
                    setGenerationError(getErrorMessage(error));
                    setGenerationState("idle");
                },
            });
        } catch (error) {
            setGenerationError(getErrorMessage(error));
            setGenerationState("idle");
        }
    };

    const handleUploadChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) {
            return;
        }

        if (uploadedPreview) {
            URL.revokeObjectURL(uploadedPreview);
        }

        setUploadedFile(file);
        setUploadedPreview(URL.createObjectURL(file));
    };

    const handleClearUpload = (event: React.MouseEvent<HTMLSpanElement>) => {
        event.stopPropagation();

        if (uploadedPreview) {
            URL.revokeObjectURL(uploadedPreview);
        }

        setUploadedFile(null);
        setUploadedPreview(null);

        if (fileInputRef.current) {
            fileInputRef.current.value = "";
        }
    };

    const getCurrentSourceFile = React.useCallback(() => {
        return selectedOutput?.file ?? uploadedFile;
    }, [selectedOutput, uploadedFile]);

    const saveCurrentOutput = React.useCallback(async () => {
        const currentFile = getCurrentSourceFile();
        if (!currentFile) {
            showActionHint("暂无可保存内容");
            return;
        }

        const nav = navigator as Navigator & {
            canShare?: (data?: ShareData) => boolean;
        };

        if (typeof nav.share === "function" && typeof nav.canShare === "function" && nav.canShare({ files: [currentFile] })) {
            try {
                await nav.share({
                    title: currentFile.name || "生成结果",
                    files: [currentFile],
                });
                showActionHint("已触发系统保存");
                return;
            } catch {
                // Fall back to browser download.
            }
        }

        const objectUrl = URL.createObjectURL(currentFile);
        const link = document.createElement("a");
        link.href = objectUrl;
        link.download = currentFile.name || "studio-output";
        link.click();
        window.setTimeout(() => {
            URL.revokeObjectURL(objectUrl);
        }, 1000);
        showActionHint("已触发下载");
    }, [getCurrentSourceFile, showActionHint]);

    const focusCreativeInput = React.useCallback(() => {
        setPreviewModal((prev) => ({ ...prev, open: false }));

        window.setTimeout(() => {
            if (creativeInputRef.current) {
                creativeInputRef.current.focus();
                creativeInputRef.current.scrollIntoView({ behavior: "smooth", block: "center" });
                return;
            }

            fileInputRef.current?.click();
        }, 60);
    }, []);

    const navigateWithHandoff = React.useCallback(async (
        targetMode: StudioMode,
        options?: { imageWorkflow?: ImageWorkflow },
    ) => {
        const currentFile = targetMode === "image" && options?.imageWorkflow === "magic" && (isVideoMode || isModelMode)
            ? (uploadedFile ?? getCurrentSourceFile())
            : getCurrentSourceFile();
        const targetPath = MODE_PATHS[targetMode];

        if (currentFile) {
            try {
                const dataUrl = await fileToDataUrl(currentFile);
                const handoffPayload: StudioMediaHandoff = {
                    targetMode,
                    imageWorkflow: options?.imageWorkflow,
                    promptText,
                    fileName: currentFile.name || "studio-output",
                    fileType: currentFile.type || "application/octet-stream",
                    dataUrl,
                };
                window.sessionStorage.setItem(HANDOFF_STORAGE_KEY, JSON.stringify(handoffPayload));
            } catch {
                // If handoff serialization fails, still navigate.
            }
        }

        setPreviewModal((prev) => ({ ...prev, open: false }));

        if (targetMode === "image" && options?.imageWorkflow) {
            router.push(`${targetPath}?tab=${options.imageWorkflow}`);
            return;
        }

        router.push(targetPath);
    }, [getCurrentSourceFile, isModelMode, isVideoMode, promptText, router, uploadedFile]);

    const regenerateFromPreview = React.useCallback(() => {
        setPreviewModal((prev) => ({ ...prev, open: false }));
        void handleGenerate();
    }, [handleGenerate]);

    const handleCopyPrompt = React.useCallback(async () => {
        const text = promptText.trim();
        if (!text) {
            showActionHint("暂无可复制描述");
            return;
        }

        try {
            await navigator.clipboard.writeText(text);
            setCopySuccessMessage("复制成功");
            showActionHint("描述已复制");
        } catch {
            showActionHint("复制失败，请手动复制");
        }
    }, [promptText, showActionHint]);

    const handleImagePreviewAction = React.useCallback((label: string) => {
        if (label === "再次生成") {
            regenerateFromPreview();
            return;
        }

        if (label === "重新描述") {
            focusCreativeInput();
            return;
        }

        if (label === "魔法改图") {
            void navigateWithHandoff("image", { imageWorkflow: "magic" });
            return;
        }

        if (label === "生成视频") {
            void navigateWithHandoff("video");
            return;
        }

        if (label === "生成模型") {
            void navigateWithHandoff("model");
        }
    }, [focusCreativeInput, navigateWithHandoff, regenerateFromPreview]);

    const handleVideoModelPreviewAction = React.useCallback((label: string) => {
        if (label === "再次生成") {
            regenerateFromPreview();
            return;
        }

        if (label === "重新描述" || label === "更新描述") {
            focusCreativeInput();
            return;
        }

        if (label === "重新改图") {
            void navigateWithHandoff("image", { imageWorkflow: "magic" });
        }
    }, [focusCreativeInput, navigateWithHandoff, regenerateFromPreview]);

    const openPreview = () => {
        let kind: "image" | "video" | "model" = "image";

        if (selectedOutput) {
            const fileName = selectedOutput.file.name?.toLowerCase() || "";
            const fileType = selectedOutput.file.type || "";

            if (fileName.endsWith(".glb") || fileName.endsWith(".gltf") || fileType.startsWith("model/")) {
                kind = "model";
            } else if (fileType.startsWith("video/")) {
                kind = "video";
            }
        } else if (isVideoMode) {
            kind = "video";
        } else if (isModelMode) {
            kind = "model";
        }

        setPreviewModal({
            open: true,
            kind,
        });
    };

    const renderModelUploadCard = () => {
        return (
            <div className={styles.modelUploadFrame}>
                <input
                    ref={fileInputRef}
                    className={styles.hiddenInput}
                    type="file"
                    accept="image/*"
                    onChange={handleUploadChange}
                />
                <button
                    className={styles.modelUploadButton}
                    type="button"
                    onClick={() => fileInputRef.current?.click()}
                >
                    {uploadedPreview ? (
                        <>
                            <img src={uploadedPreview} alt="上传预览" className={styles.modelUploadPreview} />
                            <span className={`${styles.uploadRemoveBadge} ${styles.modelUploadRemoveBadge}`} onClick={handleClearUpload} role="button" tabIndex={0} onKeyDown={(event) => {
                                if (event.key === "Enter" || event.key === " ") {
                                    event.preventDefault();
                                    event.stopPropagation();
                                    if (uploadedPreview) {
                                        URL.revokeObjectURL(uploadedPreview);
                                    }
                                    setUploadedFile(null);
                                    setUploadedPreview(null);
                                    if (fileInputRef.current) {
                                        fileInputRef.current.value = "";
                                    }
                                }
                            }}>×</span>
                        </>
                    ) : (
                        <div className={styles.modelUploadEmpty}>
                            <img src="/images/Group1312319524.png" alt="上传图片" className={styles.modelUploadIcon} />
                            <span className={styles.modelUploadText}>上传图片</span>
                        </div>
                    )}
                </button>
            </div>
        );
    };

    const renderUploadCard = () => {
        if (!isUploadMode) {
            return null;
        }

        const placeholder = isVideoMode
            ? "结合图片，描述你想生成的视频画面和动作。例如: 海浪拍打着沙滩，粉色的月亮在天空缓缓升起。"
            : imageWorkflow === "line"
                ? "结合线稿，描述你希望的颜色风格和氛围。"
                : "输入你希望这张图被改成什么样子。";
        const uploadIconSrc = isVideoMode
            ? "/images/Group 1312319562.png"
            : "/images/Group 1312319562-2.png";

        // unified combo: vertical stack on desktop, horizontal on portrait
        return (
            <div className={`${styles.uploadFrame} ${styles.promptCombo}`}>
                <input
                    ref={fileInputRef}
                    className={styles.hiddenInput}
                    type="file"
                    accept="image/*"
                    onChange={handleUploadChange}
                />
                <button
                    className={styles.promptComboUpload}
                    type="button"
                    onClick={() => fileInputRef.current?.click()}
                >
                    {uploadedPreview ? (
                        <>
                            <img src={uploadedPreview} alt="上传预览" className={styles.uploadedPreview} />
                            <span className={`${styles.uploadRemoveBadge} ${styles.promptUploadRemoveBadge}`} onClick={handleClearUpload} role="button" tabIndex={0} onKeyDown={(event) => {
                                if (event.key === "Enter" || event.key === " ") {
                                    event.preventDefault();
                                    event.stopPropagation();
                                    if (uploadedPreview) {
                                        URL.revokeObjectURL(uploadedPreview);
                                    }
                                    setUploadedFile(null);
                                    setUploadedPreview(null);
                                    if (fileInputRef.current) {
                                        fileInputRef.current.value = "";
                                    }
                                }
                            }}>×</span>
                        </>
                    ) : (
                        <img src={uploadIconSrc} alt="上传图片" className={styles.addImageIcon} />
                    )}
                </button>
                <div className={styles.promptArea}>
                    <textarea
                        ref={creativeInputRef}
                        className={`${styles.promptInput} ${styles.promptComboInput}`}
                        value={promptText}
                        onChange={(event) => setPromptText(event.target.value)}
                        onFocus={() => setIsPromptEditing(true)}
                        onBlur={() => setIsPromptEditing(false)}
                        placeholder={placeholder}
                    />
                    {isPromptEditing ? (
                        <button
                            type="button"
                            className={styles.promptDone}
                            onMouseDown={(event) => event.preventDefault()}
                            onClick={finishPromptEditing}
                        >
                            完成
                        </button>
                    ) : null}
                </div>
            </div>
        );
    };

    const renderPromptField = () => {
        if (isModelMode) {
            return null;
        }

        if (isVideoMode || isUploadMode) {
            return null;
        }

        if (imageWorkflow === "text") {
            return (
                <div className={styles.promptArea}>
                    <textarea
                        ref={creativeInputRef}
                        className={styles.promptInput}
                        value={promptText}
                        onChange={(event) => setPromptText(event.target.value)}
                        onFocus={() => setIsPromptEditing(true)}
                        onBlur={() => setIsPromptEditing(false)}
                        placeholder="例如：一个番茄头猫咪挂件，猫咪的头部是红色番茄形状，身体是橘色与白色交错，盘坐状态，可爱造型 IP形象，3D立体效果，悬浮在空中，无其他杂物，纯白色背景，工作室光照，电影级画质，产品摄影，8K，极致的细节"
                    />
                    {isPromptEditing ? (
                        <button
                            type="button"
                            className={styles.promptDone}
                            onMouseDown={(event) => event.preventDefault()}
                            onClick={finishPromptEditing}
                        >
                            完成
                        </button>
                    ) : null}
                </div>
            );
        }

        // textarea is already rendered inside renderUploadCard for line/magic
        return null;
    };

    const renderGallerySelector = () => {
        if (isModelMode) {
            return null;
        }

        const visibleOptions = isVideoMode
            ? activeGalleryOptions.slice(0, 4)
            : getVisibleImageStyleOptions(selectedStyle);

        return (
            <section className={styles.selectorSection}>
                <div className={styles.selectorHeader}>
                    <span>{sectionTitle}</span>
                    <button className={styles.moreButton} type="button" onClick={() => setShowStyleDialog(true)}>
                        <img src="/images/创意.png" alt="" className={styles.moreButtonIcon} aria-hidden="true" />
                        <span>更多</span>
                    </button>
                </div>
                <div className={isVideoMode ? styles.motionGrid : styles.optionGrid} data-layout={isVideoMode ? undefined : motionLayout}>
                    {visibleOptions.map((item) => {
                        const selected = isVideoMode ? selectedMotion === item.id : selectedStyle === item.id;
                        return (
                            <button
                                key={item.id}
                                className={isVideoMode ? styles.motionChip : styles.optionChip}
                                data-selected={selected}
                                type="button"
                                onClick={() => {
                                    if (isVideoMode) {
                                        setSelectedMotion((value) => (value === item.id ? "" : item.id));
                                        return;
                                    }
                                    setSelectedStyle((value) => (value === item.id ? "" : item.id));
                                }}
                            >
                                <PendingAsset
                                    src={item.assetPath ?? "/images/pending-asset.png"}
                                    alt={item.label}
                                    className={isVideoMode ? styles.motionThumbWrap : styles.optionThumbWrap}
                                    imageClassName={isVideoMode ? styles.motionThumb : styles.optionThumb}
                                    fallbackLabel={item.label.slice(0, 2)}
                                    fit="cover"
                                />
                                <span className={isVideoMode ? styles.motionLabel : undefined}>{item.label}</span>
                            </button>
                        );
                    })}
                </div>
            </section>
        );
    };

    const renderAdvancedDialog = () => {
        if (!showAdvancedDialog) {
            return null;
        }

        const isOrange = isModelMode;
        const visibleAdvancedGroups = advancedInputsConfig.filter((group) => isVisibilityActive(group.visibility));
        const hasEditableAdvancedInputs = visibleAdvancedGroups.some((group) =>
            (group.inputs?.some((input) => isVisibilityActive(input.visibility)) ?? false)
        );
        const canSaveAdvancedDialog = hasEditableAdvancedInputs || isModelMode;

        const renderAdvancedInput = (input: AdvancedInputItem) => {
            const value = advancedDraftValues[input.key];

            switch (input.valueType) {
                case "number":
                case "seed":
                    return (
                        <div key={input.key} className={styles.readonlyFieldRow}>
                            <span>{input.title}</span>
                            <input
                                type="number"
                                value={(value as number | undefined) ?? (input.value as number | undefined) ?? 0}
                                onChange={(event) =>
                                    setAdvancedDraftValues((prev) => ({
                                        ...prev,
                                        [input.key]: event.target.value,
                                    }))
                                }
                            />
                        </div>
                    );
                case "string":
                    return (
                        <div key={input.key} className={styles.readonlyFieldRow}>
                            <span>{input.title}</span>
                            <input
                                type="text"
                                value={(value as string | undefined) ?? (input.value as string | undefined) ?? ""}
                                onChange={(event) =>
                                    setAdvancedDraftValues((prev) => ({
                                        ...prev,
                                        [input.key]: event.target.value,
                                    }))
                                }
                            />
                        </div>
                    );
                case "float":
                    return (
                        <div key={input.key} className={styles.readonlyFieldRow}>
                            <span>{input.title}</span>
                            <input
                                type="number"
                                step="0.01"
                                value={(value as number | undefined) ?? (input.value as number | undefined) ?? 0}
                                onChange={(event) =>
                                    setAdvancedDraftValues((prev) => ({
                                        ...prev,
                                        [input.key]: parseFloat(event.target.value),
                                    }))
                                }
                            />
                        </div>
                    );
                default:
                    return null;
            }
        };

        return (
            <div className={styles.dialogBackdrop} onClick={(event) => event.target === event.currentTarget && cancelAdvancedDialog("backdrop")}>
                <div className={styles.advancedDialog} data-theme={isOrange ? "orange" : isVideoMode ? "blue" : "purple"}>
                    <div className={styles.modalHeader}>
                        <strong>高级参数</strong>
                    </div>
                    <div className={styles.dialogScrollBody}>
                        {advancedInputsConfig.length > 0 ? (
                            (() => {
                                const visibleGroups = advancedInputsConfig.filter(group => isVisibilityActive(group.visibility));
                                return visibleGroups.length > 0 ? (
                                    visibleGroups.map((group) => {
                                        const visibleInputs = group.inputs?.filter(input => isVisibilityActive(input.visibility)) || [];
                                        return visibleInputs.length > 0 ? (
                                            <div key={group.key || group.title} className={styles.advancedBlock}>
                                                {group.title && <div className={styles.sectionCaption}>{group.title}</div>}
                                                {visibleInputs.map((input) => renderAdvancedInput(input))}
                                            </div>
                                        ) : null;
                                    })
                                ) : (
                                    <div className={styles.advancedBlock}>
                                        <p>无可用高级参数</p>
                                    </div>
                                );
                            })()
                        ) : (
                            <div className={styles.advancedBlock}>
                                <p>无可用高级参数</p>
                            </div>
                        )}

                        {isModelMode ? (
                            <div className={styles.advancedBlock}>
                                <div className={styles.sliderRow}>
                                    <span>控制网强度</span>
                                    <input
                                        type="range"
                                        min="0"
                                        max="100"
                                        value={modelControlStrength}
                                        style={{ "--slider-progress": `${modelControlStrength}%` } as React.CSSProperties}
                                        onChange={(event) => setModelControlStrength(Number(event.target.value))}
                                    />
                                    <em>{modelControlStrength}</em>
                                </div>
                                <div className={styles.sliderRow}>
                                    <span>表面引导强度</span>
                                    <input
                                        type="range"
                                        min="0"
                                        max="100"
                                        value={modelSurfaceStrength}
                                        style={{ "--slider-progress": `${modelSurfaceStrength}%` } as React.CSSProperties}
                                        onChange={(event) => setModelSurfaceStrength(Number(event.target.value))}
                                    />
                                    <em>{modelSurfaceStrength}</em>
                                </div>
                                <div className={styles.sliderRow}>
                                    <span>表面采样步数</span>
                                    <input
                                        type="range"
                                        min="1"
                                        max="30"
                                        value={modelStepCount}
                                        style={{ "--slider-progress": `${(modelStepCount / 30) * 100}%` } as React.CSSProperties}
                                        onChange={(event) => setModelStepCount(Number(event.target.value))}
                                    />
                                    <em>{modelStepCount}</em>
                                </div>
                            </div>
                        ) : null}
                    </div>
                    <div className={styles.dialogFooter}>
                        <button type="button" className={styles.dialogCancelBtn} onClick={() => cancelAdvancedDialog("cancel")}>取消</button>
                        <button type="button" className={styles.dialogSaveBtn} onClick={saveAdvancedDialog} disabled={!canSaveAdvancedDialog}>保存</button>
                    </div>
                </div>
            </div>
        );
    };

    const renderStyleDialog = () => {
        if (!showStyleDialog) {
            return null;
        }

        const hasSelectedStyleOption = isVideoMode ? Boolean(selectedMotion) : Boolean(selectedStyle);

        return (
            <div className={styles.dialogBackdrop} onClick={(event) => event.target === event.currentTarget && setShowStyleDialog(false)}>
                <div className={styles.styleDialog}>
                    <div className={styles.modalHeader}>
                        <strong>{activeGalleryLabel}</strong>
                    </div>
                    <div className={styles.dialogScrollBody}>
                        <div className={styles.styleDialogGrid} data-layout={motionLayout}>
                            {activeGalleryOptions.map((item) => {
                                const selected = isVideoMode ? selectedMotion === item.id : selectedStyle === item.id;
                                return (
                                    <button
                                        key={item.id}
                                        className={styles.styleDialogItem}
                                        data-selected={selected}
                                        type="button"
                                        onClick={() => {
                                            if (isVideoMode) {
                                                setSelectedMotion((value) => (value === item.id ? "" : item.id));
                                                return;
                                            }
                                            setSelectedStyle((value) => (value === item.id ? "" : item.id));
                                        }}
                                    >
                                        <PendingAsset
                                            src={item.assetPath ?? "/images/pending-asset.png"}
                                            alt={item.label}
                                            className={styles.optionThumbWrap}
                                            imageClassName={styles.optionThumb}
                                            fallbackLabel={item.label.slice(0, 2)}
                                            fit="cover"
                                        />
                                        <span className={isVideoMode ? styles.motionLabel : undefined}>{item.label}</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                    <div className={styles.dialogFooter}>
                        <button type="button" className={styles.dialogCancelBtn} onClick={() => setShowStyleDialog(false)}>取消</button>
                        <button type="button" className={styles.dialogSaveBtn} onClick={() => setShowStyleDialog(false)} disabled={!hasSelectedStyleOption}>保存</button>
                    </div>
                </div>
            </div>
        );
    };

    const renderPreviewModal = () => {
        if (!previewModal.open) {
            return null;
        }

        return (
            <MediaPreviewModal
                open={previewModal.open}
                kind={previewModal.kind}
                mediaUrl={selectedOutput?.url || uploadedPreview}
                mediaName={selectedOutput?.file?.name}
                mediaMimeType={selectedOutput?.file?.type}
                promptText={promptText || "一只粉色的小猪在跳舞 一只粉色的小猪在跳舞 一只粉色的小猪在跳舞..."}
                thumbUrl={uploadedPreview}
                actionHint={actionHint}
                onClose={() => setPreviewModal({ ...previewModal, open: false })}
                onCopyPrompt={() => void handleCopyPrompt()}
                onSave={() => void saveCurrentOutput()}
                themeStyle={PREVIEW_THEME_VARS[mode]}
                imageActions={[]}
                sideActions={previewModal.kind === "image" ? IMAGE_ACTIONS : previewModal.kind === "video" ? VIDEO_ACTIONS : previewModal.kind === "model" ? MODEL_ACTIONS : []}
                onImageAction={handleImagePreviewAction}
                onSideAction={handleVideoModelPreviewAction}
            />
        );
    };

    const renderResultToolbar = () => {
        if (generationState !== "ready") {
            return null;
        }

        return (
            <div className={styles.resultToolbar}>
                <button type="button" onClick={openPreview} aria-label="放大预览"><Expand size={20} /></button>
                <button
                    type="button"
                    aria-label="下载结果"
                    onClick={() => {
                        if (!selectedOutput) {
                            return;
                        }
                        const link = document.createElement("a");
                        link.href = selectedOutput.url;
                        link.download = selectedOutput.file.name || "studio-output";
                        link.click();
                    }}
                >
                    <Download size={20} />
                </button>
                <button type="button" aria-label="删除结果"><Trash2 size={20} /></button>
            </div>
        );
    };

    const renderResultActions = () => {
        if (generationState !== "ready") {
            return null;
        }

        const labels = isImageMode ? IMAGE_ACTIONS : isVideoMode ? VIDEO_ACTIONS : MODEL_ACTIONS;
        const handleAction = isImageMode ? handleImagePreviewAction : handleVideoModelPreviewAction;

        return (
            <div className={styles.resultActions}>
                {labels.map((label) => (
                    <React.Fragment key={label}>
                        {isImageMode && label === "魔法改图" ? <span className={styles.resultActionDivider} aria-hidden="true" /> : null}
                        <ResultActionButton
                            label={label}
                            iconSrc={RESULT_ACTION_ICON_MAP[label]}
                            onClick={() => handleAction(label)}
                            className={styles.resultActionButton}
                            iconClassName={styles.resultActionIcon}
                            labelClassName={styles.resultActionLabel}
                        />
                    </React.Fragment>
                ))}
            </div>
        );
    };

    const renderThumbnailRail = () => {
        if (isModelMode) return null;

        const isGenerating = generationState === "generating";

        return (
            <div className={styles.thumbnailRail}>
                {visibleOutputs.map((item, index) => (
                    <button
                        key={`${item.workflowSnapshot}-${item.file.name}-${index}`}
                        className={styles.thumbnailCard}
                        data-selected={selectedThumb === index}
                        type="button"
                        onClick={() => {
                            setSelectedThumb(index);
                            setPromptText(item.promptTextSnapshot);
                            setUploadedFile(item.uploadedFileSnapshot);
                            setUploadedPreview((previousPreview) => {
                                if (previousPreview) {
                                    URL.revokeObjectURL(previousPreview);
                                }
                                return item.uploadedFileSnapshot ? URL.createObjectURL(item.uploadedFileSnapshot) : null;
                            });
                            if (!item.uploadedFileSnapshot && fileInputRef.current) {
                                fileInputRef.current.value = "";
                            }
                        }}
                    >
                        <div className={styles.thumbnailVisual}>
                            {item.file.type.startsWith("image/") ? (
                                <img src={item.url} alt={`结果 ${index + 1}`} className={styles.generatedArtworkImage} />
                            ) : item.file.type.startsWith("video/") ? (
                                <video
                                    src={item.url}
                                    className={styles.generatedArtworkImage}
                                    muted
                                    playsInline
                                    preload="metadata"
                                />
                            ) : (
                                <span>{isVideoMode ? `视频 ${index + 1}` : `成片 ${index + 1}`}</span>
                            )}
                        </div>
                    </button>
                ))}
                {isGenerating ? (
                    <button className={styles.thumbnailCard} type="button" disabled data-pending="true" aria-label="生成中">
                        <video
                            src={getLoadingVideoSrc()}
                            className={styles.thumbnailPendingVideo}
                            autoPlay
                            muted
                            loop
                            playsInline
                        />
                        {/* <svg className={styles.iosSpinner} viewBox="0 0 20 20" aria-hidden="true">
                            {[0, 1, 2, 3, 4, 5, 6, 7].map(i => (
                                <rect key={i} x="9" y="1.5" width="2" height="5" rx="1"
                                    fill="white"
                                    opacity={1 - i * 0.11}
                                    transform={`rotate(${i * 45} 10 10)`}
                                />
                            ))}
                        </svg> */}

                        {/* GIF 版本（需要时取消注释，并可注释掉上面的 iosSpinner） */}
                        <img
                            src="/images/白色版本.gif"
                            alt="生成中"
                            className={styles.pendingSpinnerGif}
                        />

                    </button>
                ) : null}
            </div>
        );
    };

    const canSelectPrevious = selectedThumb > 0;
    const canSelectNext = selectedThumb < visibleOutputs.length - 1;

    const handleSelectPrevious = () => {
        setSelectedThumb((prev) => (prev > 0 ? prev - 1 : prev));
    };

    const handleSelectNext = () => {
        setSelectedThumb((prev) => (prev < visibleOutputs.length - 1 ? prev + 1 : prev));
    };

    const getLoadingVideoSrc = () => {
        if (isImageMode) {
            if (imageWorkflow === "text") {
                return "/图片生成.webm";
            }
            if (imageWorkflow === "line" || imageWorkflow === "magic") {
                return "/图片生成.webm";
            }
        }
        if (isVideoMode) {
            return "/视频生成.webm";
        }
        if (isModelMode) {
            return "/图片生成.webm";
        }
        return "/color4bg_video.webm";
    };

    const renderRightCanvas = () => {
        if (generationState === "generating") {
            return (
                <div className={styles.resultFrame}>
                    <div className={styles.pendingContent}>
                        <PendingAsset
                            src={isModelMode ? "/images/temp33.gif" : isVideoMode ? "/images/temp22.gif" : "/images/temp0.gif"}
                            alt="生成中"
                            className={styles.emptyAssetWrap}
                            imageClassName={styles.emptyAsset}
                            fallbackLabel={isModelMode ? "模" : isVideoMode ? "影" : "图"}
                        />
                        <span>{isModelMode ? "模型生成中，请稍等..." : isVideoMode ? "视频生成中，请稍等..." : "图片生成中，请稍等..."}</span>
                    </div>
                </div>
            );
        }

        if (generationState === "idle") {
            return (
                <div className={styles.resultFrame} data-transparent="true">
                    <div className={`${styles.pendingContent} ${styles.pendingContentEmpty}`}>
                        <PendingAsset
                            src={isModelMode ? "/images/temp3.gif" : isVideoMode ? "/images/temp2.gif" : "/images/temp.gif"}
                            alt="空状态"
                            className={styles.emptyAssetWrap}
                            imageClassName={styles.emptyAsset}
                            fallbackLabel={isModelMode ? "模" : isVideoMode ? "影" : "图"}
                        />
                        <span>{emptyText}</span>
                    </div>
                </div>
            );
        }

        if (isModelMode) {
            return (
                <div className={styles.resultFrame} data-theme="model">
                    <div className={styles.modelInstruction}>
                        <img src="/images/手势.png" alt="" className={styles.modelInstructionIcon} aria-hidden="true" />
                        <span>滑动屏幕，旋转模型</span>
                    </div>
                    <button className={styles.modelExpand} type="button" onClick={openPreview} aria-label="放大预览">
                        <Expand size={24} />
                    </button>
                    <div className={`${styles.modelViewer} ${styles.modelViewerInline}`}>
                        {selectedOutput && (selectedOutput.file.type.startsWith("model/") || selectedOutput.file.name?.endsWith(".glb") || selectedOutput.file.name?.endsWith(".gltf")) ? (
                            // @ts-expect-error model-viewer is a Web Component
                            <model-viewer
                                src={selectedOutput.url}
                                alt="3D模型"
                                auto-rotate
                                camera-controls
                                style={{ width: "100%", height: "100%" }}
                            />
                        ) : selectedOutput && selectedOutput.file.type.startsWith("image/") ? (
                            <img src={selectedOutput.url} alt="生成结果" className={styles.generatedArtworkImage} />
                        ) : (
                            <div className={styles.modelSilhouette} />
                        )}
                    </div>
                    {renderResultActions()}
                </div>
            );
        }

        if (isVideoMode) {
            return (
                <div className={styles.resultFrame} data-theme="video">
                    {renderResultToolbar()}
                    <button className={styles.viewerNav} type="button" data-side="left" onClick={handleSelectPrevious} disabled={!canSelectPrevious}>
                        <ChevronLeft size={32} />
                    </button>
                    <button className={styles.viewerNav} type="button" data-side="right" onClick={handleSelectNext} disabled={!canSelectNext}>
                        <ChevronRight size={32} />
                    </button>
                    <button className={styles.videoPoster} type="button" onClick={openPreview}>
                        {selectedOutput && selectedOutput.file.type.startsWith("video/") ? (
                            <video src={selectedOutput.url} className={styles.generatedArtworkImage} controls />
                        ) : (
                            <>
                                <div className={styles.playOverlay}><Play size={34} fill="currentColor" /></div>
                                <div className={styles.videoTimeline}><span /></div>
                                <div className={styles.videoMeta}>00:04/00:05</div>
                            </>
                        )}
                    </button>
                    {renderResultActions()}
                </div>
            );
        }

        return (
            <div className={styles.resultFrame} data-theme="image">
                {renderResultToolbar()}
                <button className={styles.viewerNav} type="button" data-side="left" onClick={handleSelectPrevious} disabled={!canSelectPrevious}>
                    <ChevronLeft size={32} />
                </button>
                <button className={styles.viewerNav} type="button" data-side="right" onClick={handleSelectNext} disabled={!canSelectNext}>
                    <ChevronRight size={32} />
                </button>
                <button className={styles.generatedArtworkButton} type="button" onClick={openPreview}>
                    {selectedOutput ? (
                        <img src={selectedOutput.url} alt="生成结果" className={styles.generatedArtworkImage} />
                    ) : uploadedPreview && imageWorkflow !== "text" ? (
                        <img src={uploadedPreview} alt="生成结果" className={styles.generatedArtworkImage} />
                    ) : (
                        <div className={styles.generatedArtwork} />
                    )}
                </button>
                {renderResultActions()}
            </div>
        );
    };

    return (
        <main className={styles.studioPage} data-mode={mode} data-keyboard-open={shouldCollapseResultPanel ? "true" : "false"}>
            {background}
            <div className={styles.studioHeader}>
                <HeaderBackButton className={styles.headerBack} />

                {isImageMode ? (
                    <div className={styles.segmentTabs} role="tablist" aria-label="图片工作流">
                        {IMAGE_TABS.map((tab) => (
                            <button
                                key={tab.id}
                                type="button"
                                className={styles.segmentTab}
                                data-active={imageWorkflow === tab.id}
                                onClick={() => {
                                    imageWorkflowPanelStateRef.current[imageWorkflow] = {
                                        promptText,
                                        uploadedFile,
                                        selectedStyle,
                                        selectedThumb,
                                        generationState,
                                    };

                                    const targetOutputs = generatedOutputsRef.current.filter((output) => output.workflowSnapshot === tab.id);
                                    const firstOutput = targetOutputs[0];
                                    const savedPanelState = imageWorkflowPanelStateRef.current[tab.id];

                                    setImageWorkflow(tab.id);
                                    setGenerationError(null);

                                    if (uploadedPreview) {
                                        URL.revokeObjectURL(uploadedPreview);
                                    }

                                    if (savedPanelState) {
                                        setGenerationState(savedPanelState.generationState);
                                        setPromptText(savedPanelState.promptText);
                                        setSelectedStyle(savedPanelState.selectedStyle);
                                        setSelectedThumb(savedPanelState.selectedThumb);
                                        setUploadedFile(savedPanelState.uploadedFile);
                                        setUploadedPreview(savedPanelState.uploadedFile ? URL.createObjectURL(savedPanelState.uploadedFile) : null);
                                        if (!savedPanelState.uploadedFile && fileInputRef.current) {
                                            fileInputRef.current.value = "";
                                        }
                                        return;
                                    }

                                    setGenerationState(targetOutputs.length > 0 ? "ready" : "idle");
                                    setSelectedStyle("");
                                    setSelectedThumb(0);

                                    if (firstOutput) {
                                        setPromptText(firstOutput.promptTextSnapshot);
                                        setUploadedFile(firstOutput.uploadedFileSnapshot);
                                        setUploadedPreview(firstOutput.uploadedFileSnapshot ? URL.createObjectURL(firstOutput.uploadedFileSnapshot) : null);
                                        if (!firstOutput.uploadedFileSnapshot && fileInputRef.current) {
                                            fileInputRef.current.value = "";
                                        }
                                    } else {
                                        setPromptText("");
                                        setUploadedFile(null);
                                        setUploadedPreview(null);
                                    }
                                }}
                            >
                                <span className={styles.segmentTabLabel}>{tab.label}</span>
                            </button>
                        ))}
                    </div>
                ) : (
                    <div />
                )}

                <div className={styles.brandLockup}>
                    <PendingAsset
                        src={BRAND_LOGO_PATH}
                        alt="飞思玖·璇玑AI"
                        className={styles.brandLogoAsset}
                        imageClassName={styles.brandLogoImage}
                        fallbackLabel="AI"
                    />
                </div>
            </div>

            <div className={styles.studioContent}>
                <section className={styles.leftColumn}>
                    <div className={styles.formCard}>
                        <div className={styles.fieldHeader}>
                            <span>作品名称</span>
                            <div className={styles.workNameBox}>
                                {editingName ? (
                                    <>
                                        <input
                                            ref={workNameInputRef}
                                            value={workName}
                                            onChange={(event) => setWorkName(event.target.value)}
                                            onBlur={() => setEditingName(false)}
                                            onKeyDown={(event) => {
                                                if (event.key === "Enter") {
                                                    setEditingName(false);
                                                }
                                            }}
                                        />
                                        <button
                                            type="button"
                                            className={styles.promptDone}
                                            data-has-text={workName.trim().length > 0}
                                            onMouseDown={(event) => event.preventDefault()}
                                            onClick={() => {
                                                workNameInputRef.current?.blur();
                                                setEditingName(false);
                                            }}
                                            aria-label="完成编辑作品名称"
                                        />
                                    </>
                                ) : (
                                    <>
                                        <span
                                            className={styles.workNameValue}
                                            role="button"
                                            tabIndex={0}
                                            onClick={() => setEditingName(true)}
                                            onKeyDown={(event) => {
                                                if (event.key === "Enter" || event.key === " ") {
                                                    event.preventDefault();
                                                    setEditingName(true);
                                                }
                                            }}
                                        >
                                            {workName}
                                        </span>
                                        <button type="button" onClick={() => setEditingName(true)} aria-label="编辑作品名称">
                                            <img src={NAME_EDIT_ICON_MAP[mode]} alt="" className={styles.workNameEditIcon} aria-hidden="true" />
                                        </button>
                                    </>
                                )}
                            </div>
                        </div>

                        <section className={styles.fieldSection}>
                            <span>创意描述</span>
                            {isModelMode ? renderModelUploadCard() : renderUploadCard()}
                            {renderPromptField()}
                        </section>

                        {renderGallerySelector()}

                        <div className={styles.bottomActions}>
                            <button
                                className={styles.advancedButton}
                                type="button"
                                onClick={openAdvancedDialog}
                            >
                                <img src="/images/edit.png" alt="" className={styles.buttonIconAsset} aria-hidden="true" />
                                <span>高级参数</span>
                            </button>
                            <button className={styles.generateButton} type="button" onClick={handleGenerate} disabled={isGenerateBlocked} data-blocked={isGenerateBlocked}>
                                <img src="/images/star.png" alt="" className={styles.buttonIconAsset} aria-hidden="true" />
                                <span>{generationState === "generating" ? "生成中..." : "立即生成"}</span>
                            </button>
                        </div>

                    </div>
                </section>

                <section className={styles.rightColumn}>
                    <div ref={resultAreaRef} className={styles.resultArea} style={frozenResultAreaStyle}>
                        {renderRightCanvas()}
                        {renderThumbnailRail()}
                    </div>
                </section>
            </div>

            {renderStyleDialog()}
            {renderAdvancedDialog()}
            {renderPreviewModal()}
            <ToastNotification
                message={generationError}
                kind="error"
                duration={5000}
                onDismiss={() => setGenerationError(null)}
            />
            <ToastNotification
                message={copySuccessMessage}
                kind="success"
                duration={2000}
                onDismiss={() => setCopySuccessMessage(null)}
            />
            <ToastNotification
                message={storageHintMessage}
                kind="info"
                duration={2600}
                onDismiss={() => setStorageHintMessage(null)}
            />
        </main>
    );
}
