
import { motion } from "framer-motion";

type ContainerColorConfig = {
    container: string[];
    container1: string[];
    container2: string[];
};

export const containerColors1: ContainerColorConfig = {
    container: ['#39AFFD', '#5BC0FF', '#1E9DF5', '#4AB5FE', '#39AFFD'],
    container1: ['#8E64EE', '#A87EF5', '#7650E5', '#9B70F2', '#8E64EE'],
    container2: ['#ED7AFF', '#FF95FF', '#E060FF', '#F788FF', '#ED7AFF'],
};

export const containerColors2: ContainerColorConfig = {
    container: ['#39FDF0', '#5BFFF5', '#1ee5da', '#4af7ed', '#39fdf0'],
    container1: ['#8e64ee', '#a87ef5', '#7650e5', '#9b70f2', '#8e64ee'],
    container2: ['#64C0EE', '#7ED5FF', '#50AEE5', '#6BC8F5', '#64C0EE'],
};

export const containerColors3: ContainerColorConfig = {
    container: ['#FF1818', '#FF5B5B', '#E5251E', '#F74A4A', '#FF1818'],
    container1: ['#FFC03A', '#FFD579', '#FFBD2D', '#FFD271', '#FFC03A'],
    container2: ['#FFE100', '#FFEF63', '#FFD900', '#FFEC42', '#FFE100'],
};

function Container({ colors }: { colors: string[] }) {
    return (
        <motion.div
            className="absolute blur-[78.6px] h-[333px] left-[-313px] opacity-9 rounded-[670px] top-[-68px] w-[1194px]"
            animate={{
                x: [0, 600, -400, 500, 0],
                y: [0, -50, 30, -40, 0],
                backgroundColor: colors,
            }}
            transition={{
                duration: 8,
                repeat: Infinity,
                ease: "easeInOut",
            }}
            data-name="Container"
        />
    );
}

function Container1({ colors }: { colors: string[] }) {
    return (
        <motion.div
            className="absolute blur-[78.6px] h-[523px] left-[93px] opacity-12 rounded-[384px] top-[-258px] w-[700px]"
            animate={{
                x: [0, -500, 700, -300, 0],
                y: [0, 60, -40, 50, 0],
                backgroundColor: colors,
            }}
            transition={{
                duration: 10,
                repeat: Infinity,
                ease: "easeInOut",
            }}
            data-name="Container"
        />
    );
}

function Container2({ colors }: { colors: string[] }) {
    return (
        <motion.div
            className="absolute blur-[78.6px] left-[535px] opacity-12 rounded-[400px] size-[973px] top-[-708px]"
            animate={{
                x: [0, -600, 1000, -400, 0],
                y: [0, 80, -60, 70, 0],
                backgroundColor: colors,
            }}
            transition={{
                duration: 12,
                repeat: Infinity,
                ease: "easeInOut",
            }}
            data-name="Container"
        />
    );
}

function BackContainer({ colors = containerColors1 }: { colors?: ContainerColorConfig }) {
    return (
        <div className="absolute h-[785px] left-0 overflow-clip top-0 w-full" data-name="背景">
            <Container colors={colors.container} />
            <Container1 colors={colors.container1} />
            <Container2 colors={colors.container2} />
        </div>
    );
}

export default BackContainer;