import type { StudioMode, ImageWorkflow } from "./studio-data";

export interface WorkflowInputKeys {
    /** key for the positive prompt text field (if any) */
    promptKey: string | null;
    /** key for the image upload field (if any) */
    imageKey: string | null;
    /** key for the filename prefix field */
    prefixKey: string;
    /** key for the negative prompt (if any, usually hidden) */
    negativePromptKey: string | null;
    /** key for seed */
    seedKey: string | null;
    /** key for width */
    widthKey: string | null;
    /** key for height */
    heightKey: string | null;
}

export interface WorkflowConfig {
    /** path under /json/ to fetch the workflow JSON */
    jsonPath: string;
    /** mapping of UI fields to workflow input keys */
    keys: WorkflowInputKeys;
}

/**
 * Returns the workflow config (JSON path + input key mapping) for the given mode and image workflow.
 */
export function getWorkflowConfig(mode: StudioMode, imageWorkflow: ImageWorkflow): WorkflowConfig {
    if (mode === "video") {
        return {
            jsonPath: "/json/图生视频API.json",
            keys: {
                promptKey: "93-inputs-text",
                imageKey: "97-inputs-image",
                prefixKey: "108-inputs-filename_prefix",
                negativePromptKey: "89-inputs-text",
                seedKey: "85-inputs-noise_seed",
                widthKey: "98-inputs-width",
                heightKey: "98-inputs-height",
            },
        };
    }

    if (mode === "model") {
        return {
            jsonPath: "/json/图生3DAPI.json",
            keys: {
                promptKey: null,
                imageKey: "25-inputs-image",
                prefixKey: "20-inputs-filename_prefix",
                negativePromptKey: null,
                seedKey: "10-inputs-seed",
                widthKey: null,
                heightKey: null,
            },
        };
    }

    // mode === "image"
    switch (imageWorkflow) {
        case "line":
            return {
                jsonPath: "/json/线稿生图API.json",
                keys: {
                    promptKey: "6-inputs-text",
                    imageKey: "71-inputs-image",
                    prefixKey: "60-inputs-filename_prefix",
                    negativePromptKey: "7-inputs-text",
                    seedKey: "3-inputs-seed",
                    widthKey: null,
                    heightKey: null,
                },
            };
        case "magic":
            return {
                jsonPath: "/json/魔法改图API.json",
                keys: {
                    promptKey: "193-inputs-prompt",
                    imageKey: "197-inputs-image",
                    prefixKey: "136-inputs-filename_prefix",
                    negativePromptKey: null,
                    seedKey: "31-inputs-seed",
                    widthKey: null,
                    heightKey: null,
                },
            };
        case "text":
        default:
            return {
                jsonPath: "/json/文生图API.json",
                keys: {
                    promptKey: "8-inputs-text",
                    imageKey: null,
                    prefixKey: "18-inputs-filename_prefix",
                    negativePromptKey: "3-inputs-text",
                    seedKey: "10-inputs-seed",
                    widthKey: "5-inputs-width",
                    heightKey: "5-inputs-height",
                },
            };
    }
}
