"use client";

import * as React from "react";
import { AlertCircle, CheckCircle2, Info } from "lucide-react";
import styles from "./toast-notification.module.css";

export type ToastKind = "error" | "success" | "info";

interface ToastNotificationProps {
    message: string | null;
    kind?: ToastKind;
    /** Auto-dismiss after ms (0 = never, default 4000) */
    duration?: number;
    onDismiss?: () => void;
}

const ICONS: Record<ToastKind, React.ReactNode> = {
    error: <AlertCircle size={18} />,
    success: <CheckCircle2 size={18} />,
    info: <Info size={18} />,
};

export function ToastNotification({
    message,
    kind = "error",
    duration = 4000,
    onDismiss,
}: ToastNotificationProps) {
    const timerRef = React.useRef<number | null>(null);

    // Auto-dismiss
    React.useEffect(() => {
        if (!message || duration === 0) return;
        if (timerRef.current) window.clearTimeout(timerRef.current);
        timerRef.current = window.setTimeout(() => {
            onDismiss?.();
            timerRef.current = null;
        }, duration);
        return () => {
            if (timerRef.current) window.clearTimeout(timerRef.current);
        };
    }, [message, duration, onDismiss]);

    if (!message) return null;

    return (
        <div className={styles.toast} data-kind={kind} role="alert" aria-live="assertive">
            <span className={styles.icon}>{ICONS[kind]}</span>
            <span className={styles.text}>{message}</span>
        </div>
    );
}
